.policy {
  .ui-title {
    margin-bottom: 40px;

    @media (max-width: 767px) {
      margin-bottom: 24px;
    }
  }

  &__text {
    display: flex;
    flex-direction: column;
    gap: 20px;
    max-width: 1242px;

    color: var(--gray-text, #5C5C5C);
    font-size: 15px;
    font-style: normal;
    font-weight: 400;
    line-height: 130%; /* 19.5px */

    @media (max-width: 767px) {
      font-size: 13px;
      gap: 16px;
    }
  }
}
