@use '@/styles/vars/media';

:root {
  --container-width: 1600px;
  --container-gap: 40px;

  @media (max-width: 1023px) {
      --container-gap: 24px;
  }

  @media (max-width: 767px) {
    --container-gap: 16px;
  }
}

.container {
  $min-width: calc(var(--container-width) + var(--container-gap) + var(--container-gap));
  width: min($min-width, 100%);
  margin-inline: auto;
  padding-inline: var(--container-gap);
}
