.mobile-menu {
  background: white;
  width: 100%;
  max-height: calc(100vh );
  overflow-y: auto;
  padding: 15px var(--container-gap) var(--container-gap);

  .header__menu {
    @media (max-width: 1279px) {
      display: block;
    }
  }

  .header__phone {
    align-items: flex-start;

    @media (max-width: 1279px) {
      display: flex;
      align-items: flex-start;
      gap: 26px;
      margin-top: 24px;
      margin-bottom: 24px;
    }
  }

  .header-search {
    display: none;
  }

  [data-modal-close] {
    margin-left: auto;
    margin-bottom: 16px;
  }
}
