@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.cont-tr-preview {

  h1 {
    @include mixins.h1;
    margin-bottom: 64px;

    @media (max-width: 767px) {
      @include mixins.h1-mob;
      margin-bottom: 40px;
    }
  }

  &__body {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--grid-gap);

    @media (max-width: 1279px) {
      grid-template-columns: 1fr;
    }
  }

  &__left {
    display: flex;
    flex-direction: column;

    @media (max-width: 1279px) {
      display: contents;
    }

    h2 {
      @include mixins.h2;
      margin-bottom: 40px;

      @media (max-width: 1279px) {
        margin-bottom: 40px - 24px;
      }

      @media (max-width: 767px) {
        @include mixins.h2-mob;
        margin-bottom: 0;
      }
    }

    p {
      @include mixins.p;

      @media (max-width: 767px) {
        @include mixins.p-mob;
      }
    }

  }

  &__right {
    @include mixins.p;
    color: var(--gray-text);
    display: grid;
    grid-template-columns: 1fr;
    gap: 24px;
    height: max-content;

    @media (min-width: 1880px) {
      grid-template-columns: 1fr 1fr;
      gap: 36px var(--grid-gap);
      p:nth-of-type(2) {
        grid-row: span 2;
      }
    }

    @media (max-width: 767px) {
      @include mixins.p-mob;
      gap: 16px;
      p:nth-of-type(2) {
          order: 3;
      }
    }

    img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      border-radius: 16px;

      @media (max-width: 1880px) {
        max-height: 256px;
      }
    }
  }

  &__cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(233px, 1fr));
    gap: var(--grid-gap);
    margin-top: 24px;
    margin-bottom: 64px;

    @media (max-width: 1279px) {
      margin-top: 0;
      margin-bottom: 64px - 24px - 24px;
    }

    @media (max-width: 767px) {
      margin-bottom: 24px - 16px;
    }
  }

  &__card {
    @include mixins.h4;
    display: flex;
    align-items: center;
    gap: 16px;

    @media (max-width: 767px) {
      @include mixins.h4-mob;
      gap: 8px;
    }
  }

  &__icon {
    display: flex;
    width: 55px;
    height: 55px;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
    border-radius: 16px;
    background: var(--blue-back-btn, #EFECFE);

    @media (max-width: 767px) {
      width: 40px;
      height: 40px;
      border-radius: 8px;
    }

    i {
      color: var(--blue-accent, #246BF5);
      font-size: 32px;
      font-style: normal;
      font-weight: 400;
      line-height: 140%; /* 44.8px */

      @media (max-width: 767px) {
        font-size: 22px;
      }
    }
  }

  &__footer {
    display: flex;
    gap: 40px;
    margin-top: auto;

    @media (max-width: 1279px) {
      order: 4;
      display: grid;
      grid-template-columns: 1fr 1fr;
      margin-top: 40px - 24px;
    }

    @media (max-width: 767px) {
      grid-template-columns: 1fr;
      gap: 16px;
      margin-top: 0;
    }

    .button {
      width: 100%;

      @media (min-width: 1280px) {
        width: 285px;
      }
    }
  }

  &__grid {
    margin-top: 80px;
    display: grid;
    gap: var(--grid-gap);
    grid-template-columns: 1fr 1fr;

    @media (max-width: 767px) {
      gap: 24px;
      margin-top: 64px;
      grid-template-columns: 1fr;
    }
  }
}
