@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.about-preview {
  margin-bottom: var(--section-margin);

  &__container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;

    @media (max-width: 1880px) {
      flex-direction: column;
      align-items: flex-start;
    }

    @media (max-width: 1023px) {
      gap: 40px;
    }
  }

  &__wrap {
    display: flex;
    align-items: center;
    gap: 40px;

    @media (max-width: 1439px) {
      justify-content: space-between;
      width: 100%;
    }

    @media (max-width: 1279px) {
      br {
        display: none;
      }
    }

    @media (max-width: 1023px) {
      flex-direction: column;
      align-items: center;
      gap: 24px;
    }

    h3 {
      @include mixins.h3;

      @media (max-width: 1023px) {
        text-align: center;
      }

      @media (max-width: 767px) {
        @include mixins.h3-mob;
      }
    }
  }

  &__warnings {
    display: flex;
    align-items: center;
    gap: 16px;
    flex-shrink: 0;
    @media (max-width: 767px) {
      flex-wrap: wrap;
      justify-content: center;
    }

  }
}
