@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.section-grid {

  &__body {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--grid-gap);

    @media (max-width: 1279px) {
      grid-template-columns: 1fr;
      gap: 40px;
    }

    @media (max-width: 767px) {
      gap: 24px;
    }
  }

  &__info {
    margin-top: 64px - 40px;
    grid-column: -1/1;
    justify-self: center;

    h3 {
      @include mixins.h3;
      margin-bottom: 40px;
      text-align: center;

      @media (max-width: 767px) {
        @include mixins.h3-mob;
        margin-bottom: 24px;
      }
    }
  }

  &__info-wrap {
    display: flex;
    gap: 24px;
    align-items: center;
    justify-content: center;

    @media (max-width: 767px) {
      flex-wrap: wrap;
      gap: 8px;
    }
  }

  &--mobile-change {
    .section-grid__body {
      @media (min-width: 768px) {
        grid-template-columns: 1fr 1fr;
      }
    }
  }
}
