@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.other-services {

  &__body {
    margin-top: 64px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 80px var(--grid-gap);

    @media (max-width: 1880px) {
      grid-template-columns: repeat(3, 1fr);
    }

    @media (max-width: 1279px) {
      grid-template-columns: repeat(2, 1fr);
    }

    @media (max-width: 767px) {
      grid-template-columns: repeat(1, 1fr);
      gap: 24px;
    }
  }
}

.other-services-card {
  padding-top: 52px;
  border-top: 1px solid var(--gray-outline, #D6D6D6);
  display: flex;
  align-items: center;
  gap: 24px;
  cursor: pointer;

  @media (max-width: 767px) {
    padding-top: 24px;
    gap: 16px;
  }

  @media (hover: hover) {
    &:hover {
      p {
        color: var(--blue-accent, #246BF5);
      }

      .swiper-arrow {
        transform: translateX(5px);

        i {
          color: var(--blue-accent, #246BF5);
        }
      }
    }
  }

  p {
    @include mixins.h4;
    flex-grow: 1;
    transition: vars.$duration color vars.$timing;

    @media (max-width: 767px) {
      @include mixins.h4-mob;
      font-weight: 700;
      word-break: break-word;
    }
  }

  i {
    color: var(--blue-accent, #246BF5);
    font-size: 32px;
    font-style: normal;
    font-weight: 400;
    line-height: 140%; /* 44.8px */

    @media (max-width: 767px) {
      font-size: 22px;
    }
  }
}
