@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.agree-policy {
  color: var(--white, #FFF);
  font-size: 14px;
  font-style: normal;
  font-weight: 400;
  line-height: 140%; /* 19.6px */

  a {
    text-decoration-line: underline;
    text-underline-offset: 3px;
    cursor: pointer;
    transition: vars.$duration text-decoration-color vars.$timing;
  }
}
