@use '@/styles/vars/vars.scss';

.overlay {
  position: fixed;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 100%;
  z-index: vars.$z-index-overlay;
  background: rgba(2, 14, 60, 0.50);
  opacity: 0;
  pointer-events: none;

  transition: vars.$duration opacity vars.$timing;

  &--active {
    pointer-events: unset;
    opacity: 1;
  }
}

body:has(.modal--open > .modal-center) .overlay {
  z-index: vars.$z-index-overlay + vars.$z-index-interactive;
}
