@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.cont-card {
  background: var(--gray-back, #F5F5F5);
  border-radius: 16px;
  overflow: hidden;

  &__header {
    position: relative;
    z-index: 2;
    margin-top: 250px - 360px;

    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 40px;
    padding: 16px 24px 40px 24px;
    border-radius: 16px 16px 0 0;
    background: var(--blue-accent, #246BF5);
    color: var(--white);

    @media (max-width: 1880px) {
      margin-top: 206px - 272px;
    }

    @media (max-width: 1279px) {
      margin-top: 172px - 200px;
      flex-direction: column;
      align-items: flex-start;

      a {
        width: 100%;
      }
    }

    @media (max-width: 767px) {
      margin-top: 125px - 160px;
      padding-inline: 16px;
    }
  }

  &__header-wrap {
    h3 {
      @include mixins.h3;
      @include mixins.crop-height(2);

      @media (max-width: 767px) {
        @include mixins.h3-mob;
      }
    }

    p {
      margin-top: 9px;
      color: rgba(255, 255, 255, 0.70);
      font-size: 16px;
      font-style: normal;
      font-weight: 400;
      line-height: 130%; /* 20.8px */
    }
  }

  &__body {
    position: relative;
    z-index: 2;
    margin-top: -24px;

    padding: 24px;
    border-radius: 16px;
    background: var(--gray-back, #F5F5F5);
    display: flex;
    flex-wrap: wrap;
    gap: 12px;

    @media (max-width: 767px) {
      margin-top: -16px;
      padding: 16px;
    }
  }

  &__item {
    border-radius: 16px;
    border: 1px solid var(--blue-back-btn, #EFECFE);
    background: var(--white, #FFF);
    padding: 12px;
  }

  &__item-title {
    @include mixins.h5;
    text-transform: uppercase;
    color: var(--gray-text, #5C5C5C);
    margin-bottom: 8px;

    @media (max-width: 767px) {
      @include mixins.h5-mob;
    }
  }

  &__item-body {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;

    a {
      color: #0F2186;
      padding: 10px 16px;
      text-transform: initial;
      display: flex;
      align-items: center;
      gap: 8px;

      img {
        width: 30px;
        height: 20px;
        object-fit: contain;
        border-radius: 4px;
      }
    }
  }

  img {
    width: 100%;
    height: 360px;
    aspect-ratio: 814/360;
    border-radius: 16px 16px 0 0;
    object-fit: cover;

    @media (max-width: 1880px) {
      height: 272px;
    }

    @media (max-width: 1279px) {
      height: 200px;
    }

    @media (max-width: 767px) {
      height: 160px;
    }
  }

  &:not(:has(&__body)) {
    .cont-card__header {
      flex-direction: column;
      align-items: flex-start;
      gap: 24px;

      h3 {
        height: 58px ;
        font-weight: 400;
      }
    }
  }

  .button--white {
    @media (hover: hover) {
        &:hover {
          background: var(--white);
          border-color: var(--blue-btn);
          color: var(--blue-btn);
        }
    }
  }
}
