@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.client-error {

  &__body {
    margin-top: 40px;
    max-width: 782px;
    padding: 16px;
    border-radius: 16px;
    background: var(--gray-back, #F5F5F5);

    h3 {
      @include mixins.h3;
      margin-bottom: 40px;

      @media (max-width: 767px) {
        @include mixins.h3-mob;
        margin-bottom: 24px;
      }
    }
  }

  &__buttons {
    display: flex;
    gap: 40px;

    @media (max-width: 767px) {
      gap: 16px;
      flex-direction: column;
    }

    .button {
      flex-grow: 1;

      @media (max-width: 767px) {
        width: 100%;
      }
    }
  }
}
