$main-font: 'Inter',sans-serif;

@mixin h1 {
  font-family: $main-font;
  font-size: 48px;
  font-weight: 700;
  line-height: 57.6px;
}

@mixin h1-mob {
  font-family: $main-font;
  font-size: 28px;
  font-weight: 700;
  line-height: 33.6px;
}

@mixin h2 {
  font-family: $main-font;
  font-size: 44px;
  font-weight: 600;
  line-height: 120%;
}

@mixin h2-mob {
  font-family: $main-font;
  font-size: 24px;
  font-weight: 600;
  line-height: 28.8px;
}

@mixin h3 {
  font-family: $main-font;
  font-size: 22px;
  font-weight: 600;
  line-height: 28.6px;
}

@mixin h3-mob {
  font-family: $main-font;
  font-size: 15px;
  font-weight: 600;
  line-height: 19.5px;
}

@mixin h4 {
  font-family: $main-font;
  font-size: 20px;
  font-weight: 500;
  line-height: 130%;
}

@mixin h4-mob {
  font-family: $main-font;
  font-size: 15px;
  font-weight: 500;
  line-height: 130%;
}

@mixin h5 {
  font-family: $main-font;
  font-size: 14px;
  font-weight: 500;
  line-height: 18.2px;
  letter-spacing: 0.04em;
}

@mixin h5-mob {
  font-family: $main-font;
  font-size: 13px;
  font-weight: 500;
  line-height: 16.9px;
  letter-spacing: 0.04em;
}

@mixin button {
  font-family: $main-font;
  font-size: 15px;
  font-weight: 600;
  line-height: 18px;
  letter-spacing: 0.06em;
}

@mixin menu {
  font-family: $main-font;
  font-size: 14px;
  font-weight: 700;
  line-height: 18.2px;
}

@mixin p {
  font-family: $main-font;
  font-size: 18px;
  font-weight: 400;
  line-height: 130%;
}

@mixin p-mob {
  font-family: $main-font;
  font-size: 15px;
  font-weight: 400;
  line-height: 19.5px;
}

@mixin info {
  font-family: $main-font;
  font-size: 15px;
  font-weight: 400;
  line-height: 19.5px;
  text-align: left;
}

@mixin inputs {
  font-family: $main-font;
  font-size: 15px;
  font-style: normal;
  font-weight: 400;
  line-height: 130%; /* 19.5px */
}
