@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.submenu-content {
  background: var(--white);
  border-radius: 16px;
  display: flex;
  flex-direction: column;

  @media (width >= vars.$media-1280) {
    padding: 24px;
  }


  &__item {
    position: relative;
    width: 100%;

    @media (width >= vars.$media-1280) {
      max-width: 350px;
      padding-block: 8px;
      @media (hover: hover) {
        &:hover {
          & > .submenu-content__item-panel {
            color: var(--blue-accent);
          }
          & > .submenu-content__body {
            padding-left: 32px;
            opacity: 1;
            pointer-events: unset;
          }
        }
      }
    }

    @media (width < vars.$media-1280) {
      & > a {
        display: block;
        padding: 8px 10px;
      }

      & > .submenu-content__body {
        padding-left: 20px;
        opacity: 0;
        max-height: 0;
        overflow: hidden;
        transition: 200ms opacity linear, 300ms max-height linear
      }

      &.active {
        & > [data-id='panel'] {
          color: var(--blue-btn);
          i {
            transform: rotate(90deg);
          }

          @media (max-width: 1279px) {
            border-bottom: 1px solid var(--blue-back-btn, #EFECFE);
          }
        }

        & > [data-id='body'] {
          opacity: 1 !important;
          max-height: 500px !important;
          overflow-y: auto;
          overflow-x: hidden;
        }
      }
    }
  }

  &__item-panel {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    width: 100%;
  }

  &__body {
    background-color: var(--white);
    border-radius: 16px;
    width: 100%;
    display: flex;
    flex-direction: column;
    transition: vars.$duration opacity vars.$timing,
    vars.$duration padding vars.$timing;

    @media (width >= vars.$media-1280) {
      position: absolute;
      left: 100%;
      top: var(--body-top);
      z-index: 3;
      padding-right: 32px;
      height: var(--general-height);
      opacity: 0;
      pointer-events: none;

      .submenu-content__body {
        top: 0;
        height: auto;
        max-height: 400px;
        overflow-y: auto;
      }
    }
  }
}
