@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.deliv-price {

  &__body {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--grid-gap);

    @media (max-width: 1880px) {
      grid-template-columns: 1fr;
      row-gap: 64px;
    }

    @media (max-width: 767px) {
      row-gap: 40px;
    }
  }

  &__feedback.special-warning {
    width: fit-content;
    margin-top: 64px;
    margin-inline: auto;
    padding-inline: 8px;

    @media (max-width: 1279px) {
      br {
        display: none;
      }
    }

    @media (max-width: 767px) {
      width: 100%;
      display: grid;
      grid-template-columns: max-content 1fr;
      gap: 16px 8px;

      .button {
        grid-column: -1/1;
        width: 100%;
      }
    }

    .button {
      @media (hover: hover) {
          &:hover {
            border-color: var(--blue-btn);
          }
      }
    }
  }
}
