@use '@/styles/mixins/mixins';
@use '@/styles/vars/vars';

.card-swiper {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 40px;
  height: 530px;

  @media (max-width: 1880px) {
    height: 400px;
  }

  @media (max-width: 1279px) {
    height: auto;
  }

  &__thumb {
    display: flex;
    flex-direction: column;
    gap: 16px;
    height: inherit;

    max-width: 100%;
    min-width: 0;

    @media (max-width: 1279px) {
      grid-column: -1/1;
      flex-direction: row;
      width: 100%;
      height: auto;
      max-height: 114px;
    }

    @media (max-width: 767px) {
      display: none;
    }
  }

  &__wrap {
    grid-column: span 5;
    position: relative;
    height: inherit;
    max-width: 100%;
    min-width: 0;

    @media (max-width: 1279px) {
      grid-column: -1/1;
      order: -1;
      max-height: 932px;
    }

    @media (max-width: 767px) {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }
  }

  &__navigation {
    @media (max-width: 767px) {
      display: flex;
      align-items: center;
      gap: 16px;
      justify-content: center;
    }
  }

  &__arrow {
    position: absolute;
    z-index: vars.$z-index-interactive;
    top: 50%;
    transform: translateY(-50%);

    &--prev {
      left: 16px;
    }

    &--next {
      right: 16px;
    }

    @media (max-width: 767px) {
      position: static;
      transform: unset;
    }
  }

  &__thumb-button {
    display: flex;
    height: 32px;
    padding: 13px 10px;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
    border-radius: 4px;
    background: var(--blue-back-btn, #EFECFE);
    width: 100%;
    cursor: pointer;
    transition: vars.$duration background-color vars.$timing;

    @media (max-width: 1279px) {
      width: 32px;
      height: 100%;
    }

    @media (hover: hover) {
      &:hover:not(.swiper-button-disabled) i {
        color: var(--blue-accent, #246BF5);
      }
    }

    i {
      transition: vars.$duration color vars.$timing;

      @media (max-width: 1279px) {
        transform: rotate(-90deg);
      }
    }

    &.swiper-button-disabled {
      background: var(--gray-back, #F5F5F5);
      color: var(--gray-text);
      cursor: initial;
    }
  }

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .swiper {
    max-width: 100%;
    min-width: 0;
  }

  [data-id="thumbnail"] {
    height: inherit;

    img {
      border-radius: 4px;
    }

    .swiper-slide {
      border: 2px solid transparent;
      border-radius: 6px;
      cursor: pointer;
      transition: vars.$duration border-color vars.$timing;
    }

    .swiper-slide-thumb-active, .swiper-slide:hover {
      border-color: var(--blue-accent, #246BF5);
    }
  }

  [data-id="swiper"] {
    height: 100%;

    @media (max-width: 1279px) {
      max-height: 920px;
    }

    @include mixins.swiper-margin;

    img {
      border-radius: 16px;
    }

    .swiper-slide {
      opacity: 0;
      transition: vars.$duration opacity vars.$timing;
    }

    .swiper-slide-active {
      opacity: 1;
    }
  }
}
