@forward 'colors';
@forward 'media';
@forward 'grid';
@forward 'env';
@forward 'transition';

// Унификация z-index значения по всему проекту
$z-index-step: 5;
$z-index-back: -1;

$z-index-interactive: $z-index-step;
$z-index-overlay: $z-index-step * 100;
$z-index-modal: $z-index-overlay + $z-index-step;
// ---

:root {
  --section-margin: 110px;
  --mm-scrollbar: 17px;

  @media (max-width: 1880px) {
    --section-margin: 80px;
  }

  @media (max-width: 767px) {
    --section-margin: 64px;
  }
}
